#include <Servo.h>

// Joystick Pan-Tilt Turret
// Maps joystick X/Y axes onto two independent servo angles.

const int VRX_PIN = A0;
const int VRY_PIN = A1;

const int PAN_SERVO_PIN = 9;
const int TILT_SERVO_PIN = 10;

Servo panServo;
Servo tiltServo;

void setup() {
  panServo.attach(PAN_SERVO_PIN);
  tiltServo.attach(TILT_SERVO_PIN);
}

void loop() {
  int panAngle = map(analogRead(VRX_PIN), 0, 1023, 0, 180);
  int tiltAngle = map(analogRead(VRY_PIN), 0, 1023, 0, 180);

  panServo.write(panAngle);
  tiltServo.write(tiltAngle);

  delay(15);
}
